begin;
update public.lessons
set steps = $n9$[{"id":"l1-lesson-2-s1","body":"100 g de pan NO son 100 g de carbohidratos. El pan tiene agua, proteína, grasa y HC. Solo contamos los HC.","type":"explanation","title":"La confusión más común"},{"id":"l1-lesson-2-s2","body":"Busca \"Hidratos de carbono\" en la tabla nutricional. Ese número (por 100 g) es lo que te importa. Ignora el peso total del alimento.","type":"explanation","title":"Cómo leer la etiqueta"},{"id":"l1-lesson-2-s3","body":"(Gramos de alimento × HC por 100 g) ÷ 100 = Gramos de HC. Luego divide por 10 para obtener raciones.","type":"explanation","title":"Fórmula mágica"},{"id":"l1-lesson-2-s4","body":"125 g de yogur natural × 5 g HC/100 g = 6,25 g HC ≈ 0,6 raciones. ¡No son 12,5 raciones!","type":"example","title":"Ejemplo con yogur","foodId":"yogur-natural"},{"id":"l1-lesson-2-practice","body":"Comprueba lo aprendido con un ejercicio rápido.","type":"practice","title":"Practica ahora","exerciseId":"ex-l1-2-label-reading"}]$n9$::jsonb,
    updated_at = now()
where id = 'l1-lesson-2';
update public.lessons
set steps = $n9$[{"id":"l1-lesson-5-s1","body":"1 rebanada de pan de molde = ~10 g HC (1 ración). 1 rebanada de pan de barra = ~15 g HC (1,5 raciones). El integral tiene más fibra.","type":"example","title":"Pan y cereales","foodId":"pan-molde"},{"id":"l1-lesson-5-s2","body":"1 manzana mediana = ~15 g HC (1,5 raciones). 1 plátano pequeño = ~20 g HC (2 raciones). El zumo cuenta igual que la fruta entera.","type":"example","title":"Fruta","foodId":"manzana"},{"id":"l1-lesson-5-s3","body":"1 vaso de leche (200 ml) = ~10 g HC (1 ración). 1 yogur natural = ~5-6 g HC (0,5-0,6 raciones). Los lácteos azucarados tienen más.","type":"example","title":"Lácteos","foodId":"leche-semi-200ml"},{"id":"l1-lesson-5-s4","body":"1 ración de fruta = 1 pieza del tamaño de tu puño. 1 ración de pan = 1 rebanada fina. 1 ración de leche = 1 vaso pequeño.","type":"explanation","title":"Truco visual"},{"id":"l1-lesson-5-practice","body":"Comprueba lo aprendido con un ejercicio rápido.","type":"practice","title":"Practica ahora","exerciseId":"ex-l1-5-fruit-bread-dairy"}]$n9$::jsonb,
    updated_at = now()
where id = 'l1-lesson-5';
update public.lessons
set steps = $n9$[{"id":"l2-lesson-2-s1","body":"1 patata mediana hervida (150 g) = 23 g HC (2,3 raciones). El peso es el de la patata ya cocida.","type":"example","title":"Patata hervida","foodId":"patata-cocida-150g"},{"id":"l2-lesson-2-s1a","body":"La misma cantidad ya asada (150 g) = 69 g HC (6,9 raciones). Al horno pierde agua y el hidrato se concentra.","type":"example","title":"Patata asada","foodId":"es-patata-asada"},{"id":"l2-lesson-2-s1b","body":"100 g de patata frita = 30 g HC (3 raciones). La grasa no se suma como hidrato.","type":"example","title":"Patata frita","foodId":"patatas-fritas-100g"},{"id":"l2-lesson-2-s2","body":"1 boniato pequeño (130 g) = ~26 g HC (2,6 raciones). Es más dulce que la patata pero cuenta similar.","type":"example","title":"Boniato/batata","foodId":"boniato-asado-130g"},{"id":"l2-lesson-2-s3","body":"Cuidado: el puré de sobre puede tener leche en polvo y almidones. 100 g de puré preparado = ~12 g HC (1,2 raciones).","type":"example","title":"Puré instantáneo","foodId":"es-pure-patata"},{"id":"l2-lesson-2-s4","body":"Freír añade grasa, que no cuenta como hidrato pero retrasa la subida de glucosa. Asar no lleva ese aceite; lo que cambia el número es el agua que pierde.","type":"explanation","title":"Consejo de cocción"},{"id":"l2-lesson-2-practice","body":"Comprueba lo aprendido con un ejercicio rápido.","type":"practice","title":"Practica ahora","exerciseId":"ex-l2-2-potato-sweet-potato"}]$n9$::jsonb,
    updated_at = now()
where id = 'l2-lesson-2';
update public.lessons
set steps = $n9$[{"id":"l2-lesson-3-s1","body":"1 plato de lentejas cocidas (200 g) = ~24 g HC (2,4 raciones). Tienen 5 g de fibra, que ayuda a frenar la subida de glucosa.","type":"example","title":"Lentejas cocidas","foodId":"lentejas-cocidas-200g"},{"id":"l2-lesson-3-s2","body":"100 g de garbanzos cocidos = ~16 g HC (1,6 raciones). 100 g de alubias rojas = ~14 g HC (1,4 raciones).","type":"example","title":"Garbanzos y alubias","foodId":"garbanzos-cocidos"},{"id":"l2-lesson-3-s3","body":"Tienen proteína vegetal y mucha fibra. Por eso, aunque tienen HC, suben la glucosa más despacio que el pan o el arroz.","type":"explanation","title":"¿Por qué son especiales?"},{"id":"l2-lesson-3-s4","body":"La FEN y ADA recomiendan legumbres 2-3 veces por semana. Son parte de la dieta mediterránea y ayudan a controlar la glucemia.","type":"example","title":"Consejos FEN y ADA","foodId":"alubias-cocidas","sourceIds":["fen","ada"]},{"id":"l2-lesson-3-practice","body":"Comprueba lo aprendido con un ejercicio rápido.","type":"practice","title":"Practica ahora","exerciseId":"ex-l2-3-legumes-counting"}]$n9$::jsonb,
    updated_at = now()
where id = 'l2-lesson-3';
update public.level_exams
set pool_exercise_ids = $n9$["ex-l2-1-rice-pasta-portions","ex-l2-2-potato-sweet-potato","ex-l2-3-legumes-counting","n2-ex4","n2-ex5","n2-ex6","n2-ex7","n2-ex8","n2-ex9","n2-ex10","n2-ex11","n2-ex12"]$n9$::jsonb,
    exercise_ids = $n9$["ex-l2-1-rice-pasta-portions","ex-l2-2-potato-sweet-potato","ex-l2-3-legumes-counting","n2-ex4","n2-ex5","n2-ex6","n2-ex7","n2-ex8","n2-ex9","n2-ex10","n2-ex11","n2-ex12"]$n9$::jsonb,
